54	    /**
55	     * Add a claim for a person on the sheet; with no date it is dated the sheet's today. Refused when
56	     * it is dated inside a closed period, or when it is a correction that does not name a SETTLED claim
57	     * of the same person (see {@link #refuseUnlessCorrects}).
58	     */
59	    @Transactional
60	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
61	            String corrects) {
62	        Rollups.Rollup before = rollups.take(sheetId);
63	        Person person = person(sheetId, personId);
64	        LocalDate dated = date != null ? date : sheets.today(sheetId);
65	        LocalDate dueBy = dated.plusDays(sheets.lock(sheetId).termsFor(person.gradeOn(dated), dated));
66	        periods.refuseIfClosed(sheetId, dated);
67	        refuseIfRetired(person, dated);
68	        refuseUnlessCorrects(sheetId, personId, amount, corrects);
69	        Claim claim = claims.saveAndFlush(new Claim(sheetId, personId, money(amount), dated, dueBy, clean(note), corrects));
70	        claim = logged(claim, user, person);
71	        audited("CLAIM_ADDED", sheetId, user, person, claim);
72	        rollups.audit(sheetId, user, before);
73	        return claim;
74	    }
