76	    /**
77	     * Change a claim's amount, date, note and the number it corrects; with no date it keeps its own. Only a DRAFT claim can be
78	     * edited: an OPEN one is changed by voiding it and adding a new one. Refused when the claim, or the
79	     * date it moves to, is inside a closed period, or when it would be a correction that does not name a
80	     * SETTLED claim of the same person.
81	     */
82	    @Transactional
83	    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
84	            String corrects) {
85	        Rollups.Rollup before = rollups.take(sheetId);
86	        sheets.lock(sheetId);
87	        Claim claim = claim(sheetId, claimId);
88	        if (claim.getStatus() != ClaimStatus.DRAFT) {
89	            throw new ResponseStatusException(HttpStatus.CONFLICT,
90	                    "A " + claim.getStatus() + " claim cannot be edited; only a DRAFT can.");
91	        }
92	        periods.refuseIfClosed(sheetId, claim.getDate());
93	        if (date != null) {
94	            periods.refuseIfClosed(sheetId, date);
95	            refuseIfRetired(person(sheetId, claim.getPersonId()), date);
96	        }
97	        refuseUnlessCorrects(sheetId, claim.getPersonId(), amount, corrects);
98	        claim.change(money(amount), date != null ? date : claim.getDate(), clean(note), corrects);
99	        Claim saved = claims.saveAndFlush(claim);
100	        audited("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved);
101	        rollups.audit(sheetId, user, before);
102	        return saved;
103	    }
