105	    /**
106	     * Move a claim to a new status, recording the event; refused (and nothing written) when the
107	     * claim's current status does not allow the move. Settling fixes the claim's due at the rate
108	     * the person's grade has in force on the claim's date, or at the figure a statement bound it to,
109	     * with the late charge it has then frozen in.
110	     * Opening numbers the claim and records who opened it; a voided claim keeps its number, which
111	     * is never reused. The user who opened a claim
112	     * is refused when settling it. A clerk settling a claim whose due is above the sheet's clerk limit
113	     * (a due of n/a is within any limit) sends it PENDING instead, for a steward to approve or reject;
114	     * a steward settles any. A move the sheet's permission matrix does not allow the user's role is
115	     * refused. A claim dated inside a closed period cannot be moved, nor can a claim
116	     * deferred on the sheet's today be settled.
117	     */
118	    @Transactional
119	    public Claim move(String sheetId, String user, long claimId, ClaimStatus next) {
120	        // Every move takes the sheet's lock before reading the claim, so concurrent opens on the
121	        // sheet are serialised: each sees the other's committed claim and number.
122	        LocalDate today = sheets.lock(sheetId).getToday();
123	        Rollups.Rollup before = rollups.take(sheetId);
124	        Claim claim = claim(sheetId, claimId);
125	        periods.refuseIfClosed(sheetId, claim.getDate());
126	        String action = switch (next) {
127	            case OPEN -> "open";
128	            case SETTLED -> "settle";
129	            case VOID -> "void";
130	            case PENDING, DRAFT -> throw new IllegalArgumentException("No move to " + next + ".");
131	        };
132	        if (!roles.permits(sheetId, user, action)) {
133	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim.");
134	        }
135	        if (!claim.getStatus().canBecome(next)) {
136	            throw new ResponseStatusException(HttpStatus.CONFLICT,
137	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
138	        }
139	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(today)) {
140	            throw new ResponseStatusException(HttpStatus.CONFLICT,
141	                    "The claim is deferred until " + claim.getDeferredUntil() + ": it cannot be settled before then.");
142	        }
143	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
144	            throw new ResponseStatusException(HttpStatus.CONFLICT,
145	                    "The user who opened a claim cannot settle it.");
146	        }
147	        Person person = person(sheetId, claim.getPersonId());
148	        BigDecimal settledDue = next == ClaimStatus.SETTLED
149	                ? dues.settling(claim, person.gradeOn(claim.getDate()))
150	                : null;
151	        if (next == ClaimStatus.SETTLED) {
152	            refuseUnproved(sheetId, claim, settledDue);
153	        }
154	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, settledDue)) {
155	            next = ClaimStatus.PENDING;
156	            settledDue = null;
157	        }
158	        claim.become(next);
159	        if (next == ClaimStatus.OPEN) {
160	            claim.number(periods.nextClaimNumber(sheetId, claim.getDate()));
161	            claim.openedBy(user);
162	        }
163	        if (next == ClaimStatus.SETTLED) {
164	            claim.settleDue(settledDue);
165	        }
166	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
167	        String event = switch (next) {
168	            case OPEN -> "CLAIM_OPENED";
169	            case SETTLED -> "CLAIM_SETTLED";
170	            case PENDING -> "CLAIM_PENDING";
171	            case VOID -> "CLAIM_VOIDED";
172	            case DRAFT -> throw new IllegalStateException();
173	        };
174	        String suffix = next == ClaimStatus.SETTLED
175	                ? " due=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE)
176	                : "";
177	        audited(event, sheetId, user, person, saved, saved.getNumber(), suffix);
178	        rollups.audit(sheetId, user, before);
179	        return saved;
180	    }
