183	    @Transactional
184	    public Claim addProof(String sheetId, String user, long claimId) {
185	        sheets.lock(sheetId);
186	        Claim claim = claim(sheetId, claimId);
187	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
188	            throw new ResponseStatusException(HttpStatus.CONFLICT,
189	                    "A " + claim.getStatus() + " claim cannot take a proof.");
190	        }
191	        claim.addProof();
192	        Claim saved = claims.saveAndFlush(claim);
193	        audited("CLAIM_PROOF_ADDED", sheetId, user, person(sheetId, saved.getPersonId()), saved, saved.getNumber(),
194	                " proofs=" + saved.getProofs());
195	        return saved;
196	    }
