198	    /**
199	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it,
200	     * the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
201	     * statement. Refused when the claim is not OPEN, when the date is not after the sheet's today, or
202	     * when the claim is dated inside a closed period.
203	     */
204	    @Transactional
205	    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
206	        LocalDate today = sheets.lock(sheetId).getToday();
207	        Rollups.Rollup before = rollups.take(sheetId);
208	        Claim claim = claim(sheetId, claimId);
209	        if (claim.getStatus() != ClaimStatus.OPEN) {
210	            throw new ResponseStatusException(HttpStatus.CONFLICT,
211	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can.");
212	        }
213	        if (!until.isAfter(today)) {
214	            throw new ResponseStatusException(HttpStatus.CONFLICT,
215	                    "A claim can only be deferred to a date after the sheet's today, " + today + ".");
216	        }
217	        periods.refuseIfClosed(sheetId, claim.getDate());
218	        claim.defer(until);
219	        Claim saved = claims.saveAndFlush(claim);
220	        audited("CLAIM_DEFERRED", sheetId, user, person(sheetId, saved.getPersonId()), saved, saved.getNumber(),
221	                " until=" + until);
222	        rollups.audit(sheetId, user, before);
223	        return saved;
224	    }
