226	    /**
227	     * Approve a PENDING claim: it becomes SETTLED, its due fixed at this moment at its live figure with
228	     * the late charge it has then. Only a steward approves, and not the user who opened the claim.
229	     */
230	    @Transactional
231	    public Claim approve(String sheetId, String user, long claimId) {
232	        sheets.lock(sheetId);
233	        Rollups.Rollup before = rollups.take(sheetId);
234	        Claim claim = pending(sheetId, user, claimId);
235	        if (user.equals(claim.getOpenedBy())) {
236	            throw new ResponseStatusException(HttpStatus.CONFLICT,
237	                    "The user who opened a claim cannot approve it.");
238	        }
239	        Person person = person(sheetId, claim.getPersonId());
240	        BigDecimal approvedDue = dues.approving(claim, person.gradeOn(claim.getDate()));
241	        refuseUnproved(sheetId, claim, approvedDue);
242	        claim.settleDue(approvedDue);
243	        claim.become(ClaimStatus.SETTLED);
244	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
245	        audited("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber(),
246	                " due=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE));
247	        rollups.audit(sheetId, user, before);
248	        return saved;
249	    }
250	
251	    /**
252	     * Re-settle a SETTLED claim: its due is fixed again at the figure it would have today as an OPEN
253	     * claim bound by no statement (today's rates, grades, floor and late charge). Only a steward
254	     * re-settles; refused when the claim is not SETTLED or is dated inside a closed period.
255	     */
256	    @Transactional
257	    public Claim resettle(String sheetId, String user, long claimId) {
258	        sheets.lock(sheetId);
259	        Rollups.Rollup before = rollups.take(sheetId);
260	        Claim claim = claim(sheetId, claimId);
261	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
262	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
263	        }
264	        if (claim.getStatus() != ClaimStatus.SETTLED) {
265	            throw new ResponseStatusException(HttpStatus.CONFLICT,
266	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
267	        }
268	        periods.refuseIfClosed(sheetId, claim.getDate());
269	        Person person = person(sheetId, claim.getPersonId());
270	        BigDecimal old = claim.getSettledDue();
271	        claim.settleDue(dues.resettling(claim, person.gradeOn(claim.getDate())));
272	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
273	        audited("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber(),
274	                " old=" + (old != null ? old.toPlainString() : NO_RATE)
275	                        + " new=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE));
276	        rollups.audit(sheetId, user, before);
277	        return saved;
278	    }
279	
280	    /**
281	     * Reject a PENDING claim with a reason: it is OPEN again, bound again by its person's last
282	     * statement when that statement included it. Only a steward rejects.
283	     */
284	    @Transactional
285	    public Claim reject(String sheetId, String user, long claimId, String reason) {
286	        sheets.lock(sheetId);
287	        Rollups.Rollup before = rollups.take(sheetId);
288	        Claim claim = pending(sheetId, user, claimId);
289	        claim.become(ClaimStatus.OPEN);
290	        Claim saved = logged(claims.saveAndFlush(claim), user, person(sheetId, claim.getPersonId()));
291	        audited("CLAIM_REJECTED", sheetId, user, person(sheetId, saved.getPersonId()), saved, saved.getNumber(),
292	                " reason=" + reason.trim());
293	        rollups.audit(sheetId, user, before);
294	        return saved;
295	    }
296	
297	    /**
298	     * Move a DRAFT, OPEN or PENDING claim to another person on the sheet: it keeps its number and
299	     * date, and loses any figure a statement bound it to, its due live again until its new person's
300	     * next statement. Only a role the sheet's permission matrix allows (a steward by
301	     * default) reassigns. Refused when the claim is SETTLED or VOID, when it is
302	     * dated inside a closed period, when the new person is its own, is retired before its date, or (for
303	     * a correction) has no SETTLED claim of the number it corrects.
304	     */
305	    @Transactional
306	    public Claim reassign(String sheetId, String user, long claimId, long personId) {
307	        sheets.lock(sheetId);
308	        Rollups.Rollup before = rollups.take(sheetId);
