72	/**
73	 * The status a claim had at the end of a day (yyyy-mm-dd), as its status log records it: the last line
74	 * dated on or before it, or null when the claim was added after it. A claim with no log (added before
75	 * the log) has its current status.
76	 */
77	export function statusAt(claim: ClaimView, day: string): ClaimStatus | null {
78	  if (claim.log.length === 0) return claim.status;
79	  let then: ClaimStatus | null = null;
80	  for (const line of claim.log) {
81	    if (line.on <= day) then = line.status;
82	  }
83	  return then;
84	}
