91	/** A claim's due-by (yyyy-mm-dd), fixed when it was added. */
92	export function dueBy(claim: ClaimView): string {
93	  return claim.dueBy;
94	}
95	
96	/**
97	 * Whether a claim is deferred on the sheet's today: it is OPEN and today has not yet reached the date
98	 * it is deferred until. Until then it counts in no total, is not overdue and cannot be settled.
99	 */
100	export function deferred(claim: ClaimView, today: string): boolean {
101	  return claim.status === 'OPEN' && claim.deferredUntil !== null && today !== '' && today < claim.deferredUntil;
102	}
103	
104	/**
105	 * Whether a claim is overdue: it is OPEN or PENDING, its due-by is before the sheet's today, and it is
106	 * not deferred on it.
107	 */
108	export function overdue(claim: ClaimView, today: string): boolean {
109	  return isOpen(claim) && today !== '' && dueBy(claim) < today && !deferred(claim, today);
110	}
