112	/** What a late charge is worked from: the sheet's late percent by from-date and its today. */
113	export interface LateTerms {
114	  /** The late percent's values by from-date (see valueOn). */
115	  history: DatedValue[];
116	  /** The sheet's today (yyyy-mm-dd); empty when none is loaded. */
117	  today: string;
118	}
