120	/**
121	 * Whether a claim's live figures round half up (else half to even): when the date it rounds by is
122	 * before the policy date, or the sheet's today when no policy date is set. A correction rounds by the
123	 * date of the claim it corrects, found by number among its person's claims (its own when not found).
124	 */
125	export function roundsHalfUp(claim: ClaimView, claims: ClaimView[], policyDate: string, today: string): boolean {
126	  const corrected = claim.corrects === null
127	    ? undefined
128	    : claims.find((c) => c.personId === claim.personId && c.number === claim.corrects);
129	  const date = corrected?.date ?? claim.date;
130	  const policy = policyDate || today;
131	  return policy !== '' && date < policy;
132	}
