134	/** How many full 30 days an overdue claim is past its due-by on the sheet's today; 0 when not overdue. */
135	export function latePeriods(claim: ClaimView, late: LateTerms): number {
136	  if (!overdue(claim, late.today)) return 0;
137	  const days = (Date.parse(late.today) - Date.parse(dueBy(claim))) / 86_400_000;
138	  return Math.floor(days / 30);
139	}
