141	/**
142	 * The 30-day boundary dates (yyyy-mm-dd) an overdue claim has passed on the sheet's today: its due-by
143	 * plus 30, 60, 90 ... days, one for every full 30 days it is overdue.
144	 */
145	export function lateBoundaries(claim: ClaimView, late: LateTerms): string[] {
146	  const from = Date.parse(dueBy(claim));
147	  return Array.from({ length: latePeriods(claim, late) }, (_, i) =>
148	    new Date(from + (i + 1) * 30 * 86_400_000).toISOString().slice(0, 10));
149	}
