178	/** A two-decimal amount in whole cents, so sums are exact. */
179	export function cents(amount: string): number {
180	  const negative = amount.startsWith('-');
181	  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
182	  const abs = Number(whole) * 100 + Number(frac.padEnd(2, '0'));
183	  return negative ? -abs : abs;
184	}
