186	/** Whole cents shown with two decimals. */
187	export function money(cents: number): string {
188	  const abs = Math.abs(cents);
189	  return `${cents < 0 ? '-' : ''}${Math.trunc(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
190	}
