193	@Injectable({ providedIn: 'root' })
194	export class ClaimsApi {
195	  private readonly http = inject(HttpClient);
196	
197	  /** The sheet's claims, newest first. */
198	  list(sheet: string): Promise<ClaimView[]> {
199	    return firstValueFrom(this.http.get<ClaimView[]>(`${this.url(sheet)}/claims`));
