241	   * not a steward, and (409) when the claim is SETTLED or VOID or cannot go to that person.
242	   */
243	  reassign(sheet: string, id: number, personId: number): Promise<ClaimView> {
244	    return firstValueFrom(this.http.post<ClaimView>(`${this.url(sheet)}/claims/${id}/reassign`, { personId }));
245	  }
