249	   * person's claims newest first); those that cannot be opened are refused and left as they are.
250	   */
251	  openAll(sheet: string, claimIds: number[]): Promise<BulkOpenView> {
252	    return firstValueFrom(this.http.post<BulkOpenView>(`${this.url(sheet)}/claims/open`, { claimIds }));
253	  }
