348	        id: claim.id,
349	        message: claim.status === 'SETTLED' || claim.status === 'VOID'
350	          ? `A ${claim.status} claim cannot take a proof.`
351	          : 'The proof could not be added.',
352	      });
353	    }
354	  }
355	
356	  /** Choose the person to reassign a claim to; it clears any error left on the claim's row. */
357	  protected setReassignTo(id: number, personId: string): void {
358	    this.reassignTo.update((chosen) => ({ ...chosen, [id]: Number(personId) }));
359	    if (this.claimError()?.id === id) this.claimError.set(null);
360	  }
361	
362	  /**
363	   * Move a claim to the person chosen on its row; refused with an error on its row when none is
364	   * chosen, when the user's role may not reassign, or when the claim is SETTLED or VOID.
365	   */
366	  protected async reassign(claim: ClaimView): Promise<void> {
367	    this.claimError.set(null);
368	    const sheet = this.session.sheet();
369	    if (!sheet) return;
370	    const to = this.reassignTo()[claim.id];
371	    if (!to) {
372	      this.claimError.set({ id: claim.id, message: 'Choose a person to reassign the claim to.' });
373	      return;
374	    }
375	    try {
376	      this.saved.emit(await this.api.reassign(sheet, claim.id, to));
377	    } catch (e) {
378	      this.claimError.set({
379	        id: claim.id,
380	        message: e instanceof HttpErrorResponse && e.status === 403
381	          ? 'Your role is not allowed to reassign a claim.'
382	          : claim.status === 'SETTLED' || claim.status === 'VOID'
383	            ? `A ${claim.status} claim cannot be reassigned.`
384	            : 'The claim could not be reassigned to that person.',
385	      });
386	    }
387	  }
388	
389	  /**
390	   * Move a claim's status; a move its status does not allow is refused with an error on its row, as
391	   * is a reject without a reason. A clerk settling a claim above the clerk limit sends it PENDING.
392	   */
393	  protected async act(claim: ClaimView, action: ClaimAction): Promise<void> {
394	    this.claimError.set(null);
395	    const sheet = this.session.sheet();
396	    if (!sheet) return;
397	    const reason = (this.rejectReasons()[claim.id] ?? '').trim();
398	    if (action === 'reject' && reason === '') {
399	      this.claimError.set({ id: claim.id, message: 'Type a reason to reject the claim.' });
400	      return;
401	    }
402	    try {
403	      this.saved.emit(await this.api.act(sheet, claim.id, action, reason));
404	      if (action === 'reject') this.rejectReasons.update((reasons) => ({ ...reasons, [claim.id]: '' }));
405	    } catch (e) {
406	      const mine = claim.openedBy === this.session.user()?.trim();
407	      const own = (action === 'settle' && claim.status === 'OPEN' && mine)
408	        || (action === 'approve' && claim.status === 'PENDING' && mine);
409	      const unproved = e instanceof HttpErrorResponse && e.status === 409 && claim.proofs === 0
410	        && ((action === 'settle' && claim.status === 'OPEN') || (action === 'approve' && claim.status === 'PENDING'));
411	      const steward = e instanceof HttpErrorResponse && e.status === 403
412	        && (((action === 'approve' || action === 'reject') && claim.status === 'PENDING')
413	          || (action === 'resettle' && claim.status === 'SETTLED'));
414	      const forbidden = e instanceof HttpErrorResponse && e.status === 403
415	        && (action === 'open' || action === 'settle' || action === 'void');
416	      this.claimError.set({
417	        id: claim.id,
418	        message: forbidden
419	          ? `Your role is not allowed to ${action} a claim.`
420	          : action === 'settle' && deferred(claim, this.session.today() ?? '')
421	          ? `The claim is deferred until ${claim.deferredUntil}, so it cannot be settled before then.`
422	          : own
423	            ? `You opened this claim, so someone else must ${action} it.`
424	            : unproved
425	              ? `The claim's due is above the proof threshold, so it needs a proof before it can be ${PAST[action]}.`
426	            : steward
427	              ? `Only a steward can ${action === 'resettle' ? 're-settle' : action} a ${claim.status} claim.`
428	              : `A ${claim.status} claim cannot be ${PAST[action]}.`,
429	      });
430	    }
431	  }
432	
433	  protected reset(): void {
434	    this.editing.set(null);
435	    this.amount.set('');
436	    this.date.set('');
437	    this.note.set('');
438	    this.corrects.set('');
439	    this.error.set(null);
440	  }
441	
442	  protected async save(event: Event): Promise<void> {
443	    event.preventDefault();
444	    if (this.busy) return;
445	    this.error.set(null);
446	    const sheet = this.session.sheet();
447	    if (!sheet) return;
448	    const amount = this.amount().trim();
449	    if (!AMOUNT.test(amount)) {
450	      this.error.set('Type an amount with up to two decimals; below 0.00 only for a correction.');
451	      return;
452	    }
453	    const corrects = this.corrects().trim();
454	    if (corrects !== '' && !CLAIM_NUMBER.test(corrects)) {
455	      this.error.set('Type the number of the claim it corrects.');
456	      return;
457	    }
458	    const form = { amount, date: this.date().trim() || null, note: this.note(), corrects: corrects === '' ? null : corrects };
459	    const id = this.editing();
460	    this.busy = true;
461	    try {
462	      const claim = id === null
463	        ? await this.api.add(sheet, this.personId(), form)
464	        : await this.api.edit(sheet, id, form);
465	      this.saved.emit(claim);
466	      this.reset();
467	    } catch {
468	      const verb = id === null ? 'added' : 'saved';
469	      this.error.set(amount.startsWith('-') || corrects !== ''
470	        ? `The claim could not be ${verb}: a correction (an amount below 0.00) must name a SETTLED claim of ${this.personName()}, and only a correction names one.`
471	        : `The claim could not be ${verb}.`);
472	      if (id === null) {
473	        // a refused add leaves nothing typed behind for the next one; its refusal is still shown
474	        this.amount.set('');
475	        this.date.set('');
476	        this.note.set('');
477	        this.corrects.set('');
478	      }
479	    } finally {
480	      this.busy = false;
481	    }
482	  }
483	}
